             VALUES ('5672a3a6-7693-56f3-af73-d8d63af3ee8c', '46da42e1-395b-5b41-a81d-94ee61aad6f3', 'ai_prompt', 'Make it specific', '{"scenario":"Vague: ''Tell me about space.'' Your mission: rewrite it as a specific prompt — pick ONE planet and ask for 3 short facts.","aiTask":"You are NexLearn, a friendly tutor for absolute beginners. Follow the learner''s specific request closely. Under 80 words, simple, no jargon. The learner asked:","placeholder":"e.g. Give me 3 short facts about Mars…","checklist":["Did the answer follow YOUR details?","Is it specific, not generic?"],"exampleAnswer":"Mars is called the Red Planet because of rusty dust. It has the tallest volcano, Olympus Mons, nearly 3 times Everest''s height. A day on Mars lasts 24 hours and 37 minutes — almost like Earth!"}', '{"checklist":[true,true]}', 'See the difference? Your details shaped the answer.', '["Planet + number + short."]', 1, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('57f94a09-a560-5ef6-8ee7-c8062cbe6a82', '46da42e1-395b-5b41-a81d-94ee61aad6f3', 'fill_blank', 'Add numbers, names, and ___ to vague prompts', '{"code":"Add numbers, names, and ___ to vague prompts.","blank":"details","options":["details","emojis","shouting","silence"]}', '{"answer":"details"}', 'Details turn fog into focus.', '["Focus word."]', 2, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
