INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('6b7591e1-0ce4-529f-9872-c58efd2b5420', '1f4014eb-543d-56d0-8f27-62ff03e53472', 'ai_prompt', 'Add your context', '{"scenario":"Your mission: ask for a 3-day study plan. Give context: YOUR subject and YOUR grade.","aiTask":"You are NexLearn, a friendly tutor for absolute beginners. Use the learner''s subject and grade. Reply as a short 3-day plan, under 90 words, simple. The learner asked:","placeholder":"e.g. I am in grade 8, maths exam Friday. Make a 3-day plan…","checklist":["Does the plan mention YOUR subject?","Is it split into days or steps?"],"exampleAnswer":"Day 1: Fractions basics — 20 minutes of adding halves and quarters. Day 2: Practice 10 mixed problems and circle the tricky ones. Day 3: Redo the circled ones, then quiz yourself. You are ready, grade-8 star!"}', '{"checklist":[true,true]}', 'Context turned a generic plan into YOUR plan.', '["Subject + grade + days."]', 1, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
