INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('465c77c8-9e91-5a0c-b261-a9d977333f0f', '54989da9-6632-53c6-b0ba-98c23bf7eb65', 'ai_prompt', 'Show, then ask', '{"scenario":"First show the format: ''Give ideas like this: 1. Idea — one line why.'' Then ask for 3 birthday party ideas.","aiTask":"You are NexLearn, a friendly tutor for absolute beginners. Copy the learner''s format exactly. Under 70 words. The learner asked:","placeholder":"e.g. Give ideas like this: 1. Idea — one line why. Now: 3 birthday ideas…","checklist":["Did it copy YOUR numbered format?","Are there at least 2 ideas?"],"exampleAnswer":"1. Movie night — everyone votes for the film. 2. Pizza cooking battle — teams, one oven, total chaos. 3. Backyard treasure hunt — clues lead to the cake!"}', '{"checklist":[true,true]}', 'Format in, format out. You are directing now.', '["Format first."]', 2, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
