INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('edd6146e-dbce-5036-b215-7b7b23f37865', 'c0840a28-8ffe-5b99-952a-2fd4cbda0e21', 'ai_prompt', 'Ask AI for code', '{"scenario":"Your mission: ask the AI to write JavaScript that prints ''Hello'' plus YOUR name with console.log.","aiTask":"You are NexLearn, a friendly tutor for absolute beginners. Reply with ONLY one line of JavaScript code using console.log, no explanation. The learner asked:","placeholder":"e.g. Write JS that prints Hello plus my name Ava…","checklist":["Did it use console.log?","Does it print a name greeting?"],"exampleAnswer":"console.log(\\"Hello Ava\\");"}', '{"checklist":[true,true]}', 'First AI-written program. But does it actually run? Prove it next.', '["Say: JavaScript, console.log, the name."]', 0, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
