INSERT OR REPLACE INTO lessons (id, unit_id, title, description, sort_order, xp_reward, created_at, updated_at)
           VALUES ('2f1f4ea1-45ff-5010-93e0-0c31a22744d2', '26ec8edd-bb6b-54f4-bfdd-87304573ccb9', 'AI Makes Mistakes', 'Catch the confident bug', 1, 15, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('f49762e1-7008-5eb1-a4d2-af72a61682dd', '2f1f4ea1-45ff-5010-93e0-0c31a22744d2', 'multiple_choice', 'The AI gave you code with total confidence. You…', '{"options":["Test it before trusting it","Trust the confidence","Delete your project","Applaud"],"correctIndex":0}', '{"correctIndex":0}', 'Confidence is a tone of voice, not a correctness meter.', '["Test it."]', 0, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('d5e82173-53a7-5453-aab5-986f64596725', '2f1f4ea1-45ff-5010-93e0-0c31a22744d2', 'fix_bug', 'The AI wrote this adder, but it is wrong. Fix it to log 5.', '{"code":"// AI''s adder — looks right, runs wrong\\nfunction add(a, b) {\\n return a - b;\\n}\\nconsole.log(add(2, 3));","tests":[{"expected":"5"}]}', '{"fixed":"function add(a,b){return a+b;}console.log(add(2,3));"}', 'Minus instead of plus — the classic confident mistake. YOU caught it.', '["Minus or plus?"]', 1, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('4882d5ff-6a6f-5ae0-a43b-6b282c548f99', '2f1f4ea1-45ff-5010-93e0-0c31a22744d2', 'predict_output', 'What does the AI''s buggy version print?', '{"snippet":"function add(a,b){return a-b;}\\nconsole.log(add(2,3));","options":["-1","5","23","error"]}', '{"answer":"-1"}', '2 minus 3 is -1 — bug confirmed.', '["Minus."]', 2, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
