INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('0df6858c-2718-50e8-81a5-ccdbcb894cd8', '715856ec-9e3a-5bff-8d5a-867544632b29', 'ai_prompt', 'Ask about the error', '{"scenario":"Your mission: paste this error and ask the AI to explain it like you are 10: TypeError: undefined is not a function","aiTask":"You are NexLearn, a friendly tutor for absolute beginners. Explain the learner''s error in under 70 words with one fun everyday comparison. Zero jargon. The error is:","placeholder":"e.g. Explain this error like I am 10: TypeError…","checklist":["Did it explain WITHOUT scary jargon?","Did it give one thing to try next?"],"exampleAnswer":"Imagine pressing a TV remote button that does not exist — nothing happens and the TV complains. That is this error: your code called something that is not there. Check the spelling of the function name first!"}', '{"checklist":[true,true]}', 'Errors are clues, and now you have a translator.', '["Paste the error + like I am 10."]', 0, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
