INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('9e12c0a9-1ca5-5e8c-ab40-ff3592d46ee5', '7c8b6fe7-a65d-568f-a107-03ae07113a7a', 'predict_output', 'What prints?', '{"snippet":"for i in range(5):\\n    if i == 2:\\n        break\\nprint(i)","options":["2","1","5","Error"]}', '{"answer":"2"}', 'The loop stops when i is 2, and the print after the loop sees i still holding 2.', '["What is i at the moment it stops?"]', 2, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
