             VALUES ('4a1a8c3f-2ddb-508d-ab90-dad274e285cb', '7c8b6fe7-a65d-568f-a107-03ae07113a7a', 'predict_output', 'What prints?', '{"snippet":"count = 0\\nfor i in range(4):\\n    if i == 1:\\n        continue\\n    count = count + 1\\nprint(count)","options":["3","4","2","1"]}', '{"answer":"3"}', 'The round where i is 1 is skipped, so only 3 rounds count.', '["One round is skipped."]', 3, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
