             VALUES ('5af9e598-72ff-53a9-904f-c3cfc2335942', '28e457c7-b2d7-5e31-9845-bdecadcc009b', 'ai_prompt', 'Ask the AI to explain a function', '{"scenario":"Your mission: paste this code and ask the AI to explain what it does in one or two simple lines: def greet(name): return \\"Hi \\" + name","aiTask":"You are NexLearn, a friendly tutor for absolute beginners. Explain the learner''s Python function in under 60 words, plain language, zero jargon. The learner asked:","placeholder":"e.g. Explain what this does: def greet(name): return \\"Hi \\" + name","checklist":["Did it mention the function hands back a greeting with the name?","Was it short and free of jargon?"],"exampleAnswer":"This function takes a name, like Ava, and gives back the text \\"Hi Ava\\". The word return means it hands that text back to whoever called it."}', '{"checklist":[true,true]}', 'Now you know what defining and returning really mean.', '["Say: explain it in one or two lines."]', 6, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
