INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('843a1b1a-03fd-52e2-8588-3ee43ee148b6', 'cc66ba2d-cb97-5599-86bb-82a8ed4d1c2d', 'multiple_choice', 'Which one defines a default value?', '{"options":["def greet(name=\\"friend\\"):","def greet(name):","def greet(\\"friend\\"):","def greet(name =):"],"correctIndex":0}', '{"correctIndex":0}', 'name="friend" makes that argument optional.', '["An equals sign inside the parentheses."]', 0, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('3e4b858a-4afb-51c7-9b82-761476bcd79e', 'cc66ba2d-cb97-5599-86bb-82a8ed4d1c2d', 'predict_output', 'What prints?', '{"snippet":"def greet(name=\\"friend\\"):\\n    print(name)\\ngreet()","options":["friend","name","None","Error"]}', '{"answer":"friend"}', 'With no argument passed, the default is used.', '["The default it is."]', 1, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
