             VALUES ('55066b78-084a-5f8b-ab72-dcb1119da5ef', 'cc66ba2d-cb97-5599-86bb-82a8ed4d1c2d', 'multiple_choice', 'greet(name="Ava") uses?', '{"options":["A keyword argument","A loop","Only a default","A list"],"correctIndex":0}', '{"correctIndex":0}', 'Naming the argument like that is a keyword argument.', '["It names the value."]', 3, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
