             VALUES ('c8488d53-48d9-588c-9b49-7c01e70211ed', 'de872dee-fef9-5390-b5f9-ae95788729f5', 'multiple_choice', 'A variable created inside a function is?', '{"options":["Local to that function","Global everywhere","Deleted instantly","Always shared"],"correctIndex":0}', '{"correctIndex":0}', 'It exists only while the function runs.', '["Only inside."]', 0, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('b65f10fc-53fc-5fb5-a15f-c3c4cdbc9c78', 'de872dee-fef9-5390-b5f9-ae95788729f5', 'predict_output', 'What prints?', '{"snippet":"x = 1\\ndef f():\\n    x = 2\\nf()\\nprint(x)","options":["1","2","None","Error"]}', '{"answer":"1"}', 'The x inside f is a separate local name, so the outer x stays 1.', '["Two different x names."]', 1, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
