             VALUES ('8b760091-c9b1-50b1-b80d-dd05abefc486', 'de872dee-fef9-5390-b5f9-ae95788729f5', 'fill_blank', 'Return the local value', '{"code":"def f():\\n    ___ = 5\\n    return n\\nprint(f())","blank":"n","options":["n","y","x","f"]}', '{"answer":"n"}', 'The name must match what return sends back.', '["Match the return statement."]', 2, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
