INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('24cb5f84-ffc6-5c2d-98af-193cd4c1fa54', 'eab008d1-6514-561c-ad10-fc8fee93fcfe', 'multiple_choice', 'A traceback shows?', '{"options":["The chain of calls that led to the error","Only the fix","Your list of files","How long it took"],"correctIndex":0}', '{"correctIndex":0}', 'Read it bottom-up: the last line is the error itself.', '["It is a chain."]', 0, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
