             VALUES ('4d7bc2b2-2fba-5287-a100-54dd27ac0783', 'eab008d1-6514-561c-ad10-fc8fee93fcfe', 'multiple_choice', 'ValueError means?', '{"options":["Right type, wrong value","Wrong type","Missing file","Bad indentation"],"correctIndex":0}', '{"correctIndex":0}', 'int("hi") is the right type but an unusable value.', '["Right type, bad value."]', 1, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('c559ff55-b44a-5cb8-aa65-74c9b3004293', 'eab008d1-6514-561c-ad10-fc8fee93fcfe', 'predict_output', 'What happens when this runs?', '{"snippet":"print(int(\\"hi\\"))","options":["ValueError","0","hi","None"]}', '{"answer":"ValueError"}', 'int cannot convert hi, so it raises ValueError before printing anything.', '["It raises."]', 2, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('ae6bbd7c-4422-5750-99c4-b28e84a10f4c', 'eab008d1-6514-561c-ad10-fc8fee93fcfe', 'multiple_choice', 'Which error does 1 + "a" raise?', '{"options":["TypeError","ValueError","NameError","FileNotFoundError"],"correctIndex":0}', '{"correctIndex":0}', 'You cannot add a number and a string together, so Python raises a TypeError.', '["They are different types."]', 3, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('1c819f32-ed1a-5cf9-921a-2d1435f737bb', 'eab008d1-6514-561c-ad10-fc8fee93fcfe', 'multiple_choice', 'NameError means?', '{"options":["A name is not defined","A file is missing","A type is wrong","A number is too big"],"correctIndex":0}', '{"correctIndex":0}', 'Usually a typo, or a variable used before it exists.', '["A missing name."]', 4, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
