INSERT OR REPLACE INTO lessons (id, unit_id, title, description, sort_order, xp_reward, created_at, updated_at)
           VALUES ('39df5ed0-f23e-5166-8368-120513a27732', 'fb7493be-2720-5fb7-9089-ce3ffda45561', 'try and except', 'Handling errors instead of crashing', 1, 15, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('291baa6b-70ca-5d9b-bd43-f84d2ee5cf8d', '39df5ed0-f23e-5166-8368-120513a27732', 'multiple_choice', 'try/except lets you?', '{"options":["Handle errors instead of crashing","Run faster","Skip indentation","Delete errors"],"correctIndex":0}', '{"correctIndex":0}', 'You catch the problem and decide what happens next.', '["You catch it."]', 0, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('491a2940-3ff1-54fb-adbb-e289c19fe727', '39df5ed0-f23e-5166-8368-120513a27732', 'fill_blank', 'Catch the conversion error', '{"code":"try:\\n    n = int(\\"hi\\")\\n___ ValueError:\\n    print(\\"bad\\")","blank":"except","options":["except","catch","rescue","handle"]}', '{"answer":"except"}', 'except names the error you want to catch.', '["It is not catch."]', 1, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('7227eb69-705b-5fcb-a7c5-3a80a7db865e', '39df5ed0-f23e-5166-8368-120513a27732', 'predict_output', 'What prints?', '{"snippet":"try:\\n    print(int(\\"hi\\"))\\nexcept ValueError:\\n    print(\\"bad\\")","options":["bad","hi","ValueError","Error"]}', '{"answer":"bad"}', 'The error is caught, so the except block runs.', '["The handler prints."]', 2, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('9c86b912-3fdc-5301-8182-23d832c97176', '39df5ed0-f23e-5166-8368-120513a27732', 'multiple_choice', 'Code in a finally block runs?', '{"options":["Always","Only on error","Only on success","Never"],"correctIndex":0}', '{"correctIndex":0}', 'finally runs either way, which makes it good for cleanup.', '["Every time."]', 3, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
