             VALUES ('1de791aa-d47f-5689-9d4c-d022d80ba5c9', '39df5ed0-f23e-5166-8368-120513a27732', 'multiple_choice', 'Which one catches almost any error?', '{"options":["except Exception:","except Error:","except All:","except *:"],"correctIndex":0}', '{"correctIndex":0}', 'Exception is the base class for most built-in errors.', '["The base type."]', 4, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
