             VALUES ('53e75c63-fe03-5557-8c26-058e22a1eb66', '39df5ed0-f23e-5166-8368-120513a27732', 'predict_output', 'What prints?', '{"snippet":"try:\\n    print(1 / 0)\\nexcept ZeroDivisionError:\\n    print(\\"no\\")","options":["no","0","1.0","ZeroDivisionError"]}', '{"answer":"no"}', 'Dividing by zero raises, and the handler prints no.', '["It is caught."]', 5, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
