INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('3e1fe688-d024-50de-bfee-4b0484637c69', '9c23adb8-7da9-57c5-8478-c6110d83d52d', 'multiple_choice', 'Which one opens a file for writing?', '{"options":["open(\\"f.txt\\", \\"w\\")","open(\\"f.txt\\")","open(\\"f.txt\\", \\"r\\")","write(\\"f.txt\\")"],"correctIndex":0}', '{"correctIndex":0}', 'The mode tells Python what you plan to do.', '["Set the mode."]', 0, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
