             VALUES ('0be2a149-7156-5673-aa0b-d7ecd1ee6d7f', '9c23adb8-7da9-57c5-8478-c6110d83d52d', 'multiple_choice', 'Why use with open(...) as f?', '{"options":["It closes the file for you","It runs faster","It encrypts the file","It prints the file"],"correctIndex":0}', '{"correctIndex":0}', 'with closes the file even if an error happens inside.', '["Automatic cleanup."]', 1, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
