INSERT OR REPLACE INTO exercises (id, lesson_id, type, prompt, content, solution, explanation, hints, sort_order, created_at, updated_at)
             VALUES ('6cbedde4-7780-523b-8c8e-77ee03395ebf', 'ee565e79-3124-50ca-b897-9f3136c993e5', 'ai_prompt', 'Plan your capstone with the AI', '{"scenario":"Capstone plan: ask the AI to break a command-line to-do list into 3 small steps. Your program should keep the todos in a list and print them with a loop.","aiTask":"You are NexLearn, a friendly tutor for absolute beginners. Break the learner''s project into exactly 3 short numbered steps mentioning a list and a loop. Under 90 words, simple. The learner asked:","placeholder":"e.g. Break a command-line to-do app into 3 steps using a list and a loop","checklist":["Does the plan have numbered steps?","Does it mention a list or a loop?"],"exampleAnswer":"1. Create an empty list called todos to hold your tasks. 2. Add tasks with todos.append(\\"task\\") and print how many you have. 3. Loop over them with for t in todos: and print each one, then run it and test."}', '{"checklist":[true,true]}', 'You planned it with the AI and stayed in charge of the design.', '["Ask for 3 steps plus a list or loop."]', 0, '2026-10-24T15:13:36.315Z', '2026-10-24T15:13:36.315Z');
